def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_alive = 0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 100:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0 if hp > 3 else 45.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 16
    medium_supply = supply <= 20
    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if urgent:
        bid = max(62.0, highest_prev + 2.0)
        return float(min(budget, bid))

    if tight_supply:
        if highest_prev >= 120 and hp >= 5:
            bid = 8.0
        elif pressured:
            bid = max(58.0, min(95.0, highest_prev * 0.72 + 4.0))
        else:
            bid = max(18.0, min(55.0, avg_prev * 0.35 + 6.0))
    elif medium_supply:
        if highest_prev >= 130 and hp >= 6:
            bid = 16.0
        elif highest_prev >= 100:
            bid = max(42.0, min(78.0, highest_prev * 0.58 + 3.0))
        else:
            bid = max(34.0, avg_prev * 0.55 + 5.0)
    else:
        if highest_prev >= 120:
            bid = max(28.0, min(60.0, highest_prev * 0.42))
        else:
            bid = max(30.0, avg_prev * 0.5 + 4.0)

    if rich_alive >= 2 and hp >= 5 and highest_prev >= 120:
        bid *= 0.9

    if pressured:
        bid += 10.0

    if hp >= 8 and budget < 140:
        bid *= 0.85

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Identify alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # If no opponents alive, conserve budget
    if not alive:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Reaction to yesterday: detect who was under pressure (low survival / death)
    # and who was bidding hard (high previous bid).
    prev_bids = []
    death_like = 0
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
        # If yesterday ended badly, treat as unreliable/volatile
        if o.get('hp', 0) <= 0 or prev.get('hp_after', 0) <= 0:
            death_like += 1

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: less supply => more likely others overbid; we choose a mid strategy.
    # Convert to a rough multiplier using integer index safety.
    # (Use only for scaling; no list indexing.)
    supply_ratio = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY) + 1e-9)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid level depends on my HP.
    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))

    # If I'm in danger, bid higher to secure water.
    if hp <= 2:
        target = DAILY_SALARY * (0.85 if highest_prev_bid < DAILY_SALARY else 0.95)
    elif hp <= 4:
        target = DAILY_SALARY * (0.65 if highest_prev_bid < DAILY_SALARY else 0.75)
    else:
        # Healthy: avoid overpaying against high bidders (Bob/Cindy pattern)
        # If someone bid extremely high yesterday, slightly undercut.
        if highest_prev_bid >= DAILY_SALARY * 1.6:
            target = DAILY_SALARY * (0.45 + 0.15 * (1.0 - supply_ratio))
        else:
            # Moderate: bid enough to compete when supply is low.
            target = DAILY_SALARY * (0.55 + 0.20 * (1.0 - supply_ratio))

    # If multiple opponents look like they died/failed, we can be a bit less aggressive.
    if death_like >= 1:
        target *= 0.95

    # Never exceed budget; also cap to avoid catastrophic overspending.
    # Keep a safety cap below daily salary to preserve multi-day survival.
    cap = DAILY_SALARY * 0.85
    bid = min(budget, target, cap)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
